import { Elysia, t } from "elysia";
import { Database } from "bun:sqlite";
import { join } from "path";

const DB_DIR = join(import.meta.dir, "../ORV");

const content = new Database(join(DB_DIR, "Content.db"), { readonly: true });
const media = new Database(join(DB_DIR, "Media.db"), { readonly: true });

// Prepared statements
const stmtAllPages = content.query<
  { id: number; slug: string; title: string },
  []
>("SELECT id, slug, title FROM pages ORDER BY title");

const stmtPageBySlug = content.query<
  { id: number; slug: string; title: string; markdown: string; created_at: string },
  [string]
>("SELECT id, slug, title, markdown, created_at FROM pages WHERE slug = ?");

const stmtPageById = content.query<
  { id: number; slug: string; title: string; markdown: string; created_at: string },
  [number]
>("SELECT id, slug, title, markdown, created_at FROM pages WHERE id = ?");

const stmtSearch = content.query<
  { id: number; slug: string; title: string },
  [string]
>("SELECT id, slug, title FROM pages WHERE markdown LIKE ? OR title LIKE ? LIMIT 30");

const stmtPageImages = content.query<
  { media_id: number; alt: string; position: number },
  [number]
>(
  "SELECT media_id, alt, position FROM page_images WHERE page_id = ? ORDER BY position"
);

const stmtMediaById = media.query<
  { mime: string; data: Uint8Array },
  [number]
>("SELECT mime, data FROM media WHERE id = ?");

const stmtMediaMeta = media.query<
  { id: number; sha256: string; origin_url: string; mime: string; ext: string; size: number; created_at: string },
  [number]
>("SELECT id, sha256, origin_url, mime, ext, size, created_at FROM media WHERE id = ?");

function resolveMediaTokens(markdown: string, base: string): string {
  return markdown.replace(
    /!\[([^\]]*)\]\(media:(\d+)\)/g,
    (_, alt, id) => `![${alt}](${base}/${id})`
  );
}

const orv = new Elysia({ prefix: "/db/orv" })
  // --- Pages ---
  .get("/pages", () => {
    return stmtAllPages.all();
  })

  .get(
    "/pages/slug/:slug",
    ({ params, query }) => {
      const row = stmtPageBySlug.get(params.slug);
      if (!row) return new Response("Not found", { status: 404 });

      const mediaBase = query.mediaBase ?? "/db/orv/media";
      const images = stmtPageImages.all(row.id);
      return {
        id: row.id,
        slug: row.slug,
        title: row.title,
        markdown: resolveMediaTokens(row.markdown, mediaBase),
        images,
        created_at: row.created_at,
      };
    },
    {
      params: t.Object({ slug: t.String() }),
      query: t.Object({ mediaBase: t.Optional(t.String()) }),
    }
  )

  .get(
    "/pages/:id",
    ({ params, query }) => {
      const id = Number(params.id);
      if (!Number.isInteger(id) || id < 1)
        return new Response("Bad request", { status: 400 });

      const row = stmtPageById.get(id);
      if (!row) return new Response("Not found", { status: 404 });

      const mediaBase = query.mediaBase ?? "/db/orv/media";
      const images = stmtPageImages.all(row.id);
      return {
        id: row.id,
        slug: row.slug,
        title: row.title,
        markdown: resolveMediaTokens(row.markdown, mediaBase),
        images,
        created_at: row.created_at,
      };
    },
    {
      params: t.Object({ id: t.String() }),
      query: t.Object({ mediaBase: t.Optional(t.String()) }),
    }
  )

  .get(
    "/pages/search",
    ({ query }) => {
      const q = query.q?.trim();
      if (!q || q.length < 2)
        return new Response("Query too short", { status: 400 });
      const like = `%${q}%`;
      return stmtSearch.all(like, like);
    },
    { query: t.Object({ q: t.Optional(t.String()) }) }
  )

  .get(
    "/pages/:id/images",
    ({ params }) => {
      const id = Number(params.id);
      if (!Number.isInteger(id) || id < 1)
        return new Response("Bad request", { status: 400 });
      return stmtPageImages.all(id);
    },
    { params: t.Object({ id: t.String() }) }
  )

  // --- Media ---
  .get(
    "/media/:id",
    ({ params }) => {
      const id = Number(params.id);
      if (!Number.isInteger(id) || id < 1)
        return new Response("Bad request", { status: 400 });

      const row = stmtMediaById.get(id);
      if (!row) return new Response("Not found", { status: 404 });

      return new Response(row.data, {
        headers: {
          "Content-Type": row.mime,
          "Cache-Control": "public, max-age=31536000, immutable",
        },
      });
    },
    { params: t.Object({ id: t.String() }) }
  )

  .get(
    "/media/:id/meta",
    ({ params }) => {
      const id = Number(params.id);
      if (!Number.isInteger(id) || id < 1)
        return new Response("Bad request", { status: 400 });

      const row = stmtMediaMeta.get(id);
      if (!row) return new Response("Not found", { status: 404 });
      return row;
    },
    { params: t.Object({ id: t.String() }) }
  );

const app = new Elysia()
  .use(orv)
  .get("/", () => ({ status: "ok", prefix: "/db/orv" }))
  .listen(3000);

console.log(`ORV backend running at http://localhost:${app.server!.port}`);
console.log("Routes:");
console.log("  GET /db/orv/pages                   — all pages (id, slug, title)");
console.log("  GET /db/orv/pages/:id               — page by numeric id");
console.log("  GET /db/orv/pages/slug/:slug        — page by slug");
console.log("  GET /db/orv/pages/search?q=...      — text search");
console.log("  GET /db/orv/pages/:id/images        — images on a page");
console.log("  GET /db/orv/media/:id               — raw image blob");
console.log("  GET /db/orv/media/:id/meta          — image metadata");

