import { Elysia, t } from "elysia";
import { Database } from "bun:sqlite";
import { join } from "path";
import { readdirSync, statSync, existsSync } from "fs";

// ---------------------------------------------------------------------------
// Database registry
// ---------------------------------------------------------------------------

const ROOT = join(import.meta.dir, "../db");

interface DbEntry {
  name: string;
  label: string;
  contentPath: string;
  mediaPath: string;
  content: Database;
  media: Database;
  stats: {
    pages: number;
    media: number;
    pageImages: number;
  };
}

function discoverDatabases(): DbEntry[] {
  const entries: DbEntry[] = [];

  for (const dir of readdirSync(ROOT)) {
    const full = join(ROOT, dir);
    if (!statSync(full).isDirectory()) continue;
    if (dir === "backend" || dir.startsWith(".")) continue;

    const contentPath = join(full, "Content.db");
    const mediaPath = join(full, "Media.db");
    if (!existsSync(contentPath) || !existsSync(mediaPath)) continue;

    const content = new Database(contentPath, { readonly: true });
    const media = new Database(mediaPath, { readonly: true });

    entries.push({
      name: dir.toLowerCase(),
      label: dir,
      contentPath,
      mediaPath,
      content,
      media,
      stats: {
        pages: (content.query<{ n: number }, []>("SELECT count(*) as n FROM pages").get()?.n ?? 0),
        media: (media.query<{ n: number }, []>("SELECT count(*) as n FROM media").get()?.n ?? 0),
        pageImages: (content.query<{ n: number }, []>("SELECT count(*) as n FROM page_images").get()?.n ?? 0),
      },
    });
  }

  return entries;
}

const registry = new Map<string, DbEntry>();
for (const entry of discoverDatabases()) {
  registry.set(entry.name, entry);
}

// ---------------------------------------------------------------------------
// Prepared statement cache (per-database)
// ---------------------------------------------------------------------------

interface Statements {
  allPages: ReturnType<Database["query"]>;
  pageBySlug: ReturnType<Database["query"]>;
  pageById: ReturnType<Database["query"]>;
  search: ReturnType<Database["query"]>;
  pageImages: ReturnType<Database["query"]>;
  mediaById: ReturnType<Database["query"]>;
  mediaMeta: ReturnType<Database["query"]>;
}

const stmtCache = new Map<string, Statements>();

function stmts(name: string): Statements | null {
  if (stmtCache.has(name)) return stmtCache.get(name)!;
  const db = registry.get(name);
  if (!db) return null;

  const s: Statements = {
    allPages: db.content.query("SELECT id, slug, title FROM pages ORDER BY title"),
    pageBySlug: db.content.query("SELECT id, slug, title, markdown, created_at FROM pages WHERE slug = ?"),
    pageById: db.content.query("SELECT id, slug, title, markdown, created_at FROM pages WHERE id = ?"),
    search: db.content.query(
      "SELECT id, slug, title FROM pages WHERE title LIKE ? OR markdown LIKE ? LIMIT 30"
    ),
    pageImages: db.content.query(
      "SELECT media_id, alt, position FROM page_images WHERE page_id = ? ORDER BY position"
    ),
    mediaById: db.media.query("SELECT mime, data FROM media WHERE id = ?"),
    mediaMeta: db.media.query(
      "SELECT id, sha256, origin_url, mime, ext, size, created_at FROM media WHERE id = ?"
    ),
  };

  stmtCache.set(name, s);
  return s;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function resolveMediaTokens(markdown: string, base: string): string {
  return markdown.replace(
    /!\[([^\]]*)\]\(media:(\d+)\)/g,
    (_, alt, id) => `![${alt}](${base}/${id})`
  );
}

function notFound() {
  return new Response("Not found", { status: 404 });
}
function badRequest(msg = "Bad request") {
  return new Response(msg, { status: 400 });
}

// ---------------------------------------------------------------------------
// Routes
// ---------------------------------------------------------------------------

const app = new Elysia()

  // --- Discovery ---
  .get("/db/all", () => {
    return Array.from(registry.values()).map((e) => ({
      name: e.name,
      label: e.label,
      prefix: `/db/${e.name}`,
      stats: e.stats,
    }));
  })

  // --- Pages listing ---
  .get(
    "/db/:db/pages",
    ({ params }) => {
      const s = stmts(params.db);
      if (!s) return notFound();
      return s.allPages.all();
    },
    { params: t.Object({ db: t.String() }) }
  )

  // --- Search (must come before /:id) ---
  .get(
    "/db/:db/pages/search",
    ({ params, query }) => {
      const s = stmts(params.db);
      if (!s) return notFound();
      const q = query.q?.trim();
      if (!q || q.length < 2) return badRequest("Query too short (min 2 chars)");
      const like = `%${q}%`;
      return s.search.all(like, like);
    },
    {
      params: t.Object({ db: t.String() }),
      query: t.Object({ q: t.Optional(t.String()) }),
