        },
      });
    },
    { params: t.Object({ db: t.String(), id: t.String() }) }
  )

  // --- Media metadata ---
  .get(
    "/db/:db/media/:id/meta",
    ({ params }) => {
      const s = stmts(params.db);
      if (!s) return notFound();
