@use 'tokens' as *;

@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=Kode+Mono:wght@400;500&display=swap');

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

body {
  font-family: $font-sans;
  font-size: $text-base;
  font-weight: $weight-regular;
  line-height: $leading-normal;
  color: $text-primary;
  background-color: $surface-bg;
  min-height: 100dvh;
}

a {
  color: $color-primary;
  text-decoration: none;

  &:hover { text-decoration: underline; }
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

input, textarea {
  font-family: inherit;
}

// ── Scrollbar ────────────────────────────────────────────────────────────────
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb {
  background: $separator-opaque;
  border-radius: $radius-pill;
}

// ── Utility classes ──────────────────────────────────────────────────────────
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

