import type { PageServerLoad } from './$types';
import { error } from '@sveltejs/kit';

export const load: PageServerLoad = async ({ fetch, params }) => {
  const [dbsRes, pagesRes] = await Promise.all([
    fetch('/db/all'),
    fetch(`/db/${params.name}/pages`),
  ]);

  if (!pagesRes.ok) error(404, `Database "${params.name}" not found`);

  const [databases, pages] = await Promise.all([
    dbsRes.json(),
    pagesRes.json(),
  ]);

  const db = databases.find((d: { name: string }) => d.name === params.name);

  return {
    dbName: params.name,
    dbLabel: db?.label ?? params.name,
    pages,
  };
};

