$pages = (Invoke-RestMethod "http://localhost:3000/db/orv/pages")
Write-Host "Total pages:" $pages.Count

# Find unique prefixes/categories
$prefixes = $pages | ForEach-Object { $_.title -replace '^\<','<' } | ForEach-Object {
  if ($_ -match '^Chapter') { "Chapter" }
  elseif ($_ -match '^<') { "Special (<…>)" }
  elseif ($_ -match '^\d') { "#" }
  else { $_.Substring(0,1).ToUpper() }
} | Group-Object | Sort-Object Name | Select-Object Name, Count
$prefixes | ConvertTo-Json

