const BACKEND = env.BACKEND_URL ?? 'http://localhost:3000';

export interface PageRow {
  id: number;
  slug: string;
  title: string;
  num?: number; // parsed number for Chapter/Episode entries
}

function classifyTitle(title: string): 'chapter' | 'episode' | 'other' {
  if (/^chapter\s+\d/i.test(title)) return 'chapter';
  if (/^episode\s+\d/i.test(title)) return 'episode';
  return 'other';
}

function parseNum(title: string): number {
  const m = title.match(/\d+/);
  return m ? parseInt(m[0], 10) : 0;
}

export const load: PageServerLoad = async ({ fetch, params }) => {
  const [dbsRes, pagesRes] = await Promise.all([
    fetch(`${BACKEND}/db/all`),
    fetch(`${BACKEND}/db/${params.name}/pages`),
  ]);

  if (!pagesRes.ok) error(404, `Database "${params.name}" not found`);

  const [databases, rawPages]: [{ name: string; label: string }[], { id: number; slug: string; title: string }[]] =
    await Promise.all([dbsRes.json(), pagesRes.json()]);

  const db = databases.find((d) => d.name === params.name);

  const chapters: PageRow[] = [];
  const episodes: PageRow[] = [];
  const others: PageRow[] = [];

  for (const p of rawPages) {
    const kind = classifyTitle(p.title);
    const row: PageRow = { ...p, num: kind !== 'other' ? parseNum(p.title) : undefined };
    if (kind === 'chapter') chapters.push(row);
    else if (kind === 'episode') episodes.push(row);
    else others.push(row);
  }

  chapters.sort((a, b) => (a.num ?? 0) - (b.num ?? 0));
  episodes.sort((a, b) => (a.num ?? 0) - (b.num ?? 0));
  others.sort((a, b) => a.title.localeCompare(b.title));

  return {
    dbName: params.name,
    dbLabel: db?.label ?? params.name,
    chapters,
    episodes,
    others,
  };
};

