import type { PageServerLoad } from './$types';
import { error } from '@sveltejs/kit';
import { env } from '$env/dynamic/private';

const BACKEND = env.BACKEND_URL ?? 'http://localhost:3000';

export const load: PageServerLoad = async ({ fetch, params, url }) => {
  // mediaBase points to the frontend proxy so the browser can fetch images via /db/…/media/:id
  const mediaBase = `${url.origin}/db/${params.name}/media`;
  const res = await fetch(
    `${BACKEND}/db/${params.name}/pages/slug/${params.slug}?mediaBase=${encodeURIComponent(mediaBase)}`
  );

  if (res.status === 404) error(404, `Page "${params.slug}" not found`);
  if (!res.ok) error(500, 'Failed to load page');

  const page = await res.json();

  return {
    dbName: params.name,
    page,
  };
};

